package com.lexorion.payroll.repository;import com.lexorion.payroll.domain.PayrollEmployee;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;public interface PayrollEmployeeRepository extends JpaRepository<PayrollEmployee,UUID>{List<PayrollEmployee> findByWorkspaceIdOrderByEmployeeCodeAsc(UUID workspaceId);Optional<PayrollEmployee> findByWorkspaceIdAndEmployeeCode(UUID workspaceId,String employeeCode);boolean existsByWorkspaceIdAndEmployeeCode(UUID workspaceId,String employeeCode);@Lock(jakarta.persistence.LockModeType.PESSIMISTIC_WRITE)@Query("select e from PayrollEmployee e where e.workspace.id=:workspaceId and e.employeeCode=:employeeCode")Optional<PayrollEmployee> findScopedForUpdate(@Param("workspaceId")UUID workspaceId,@Param("employeeCode")String employeeCode);@Query("select e.employeeCode from PayrollEmployee e where e.workspace.id=:workspaceId and e.status=com.lexorion.payroll.domain.PayrollStatus.ACTIVE order by e.employeeCode")List<String> findActiveCodes(@Param("workspaceId") UUID workspaceId);}
